(()=>{const g=__rhf.game; g.state.settings.autoQuality=false; g.setQuality('high'); g.dpr=1; g.renderer.setPixelRatio(1); g.resize(); g.bears.directorT=9999; const we=g.env.weather; we.cloud=0.2; we.cloudTarget=0.2; we.rain=0; we.rainTarget=0; we.timer=9999; g.hud.firstShown=-1000; g.hud.hint('',0); g.hud.show(false); __rhf.god(true); g.env.timeScale=0; g.wildlife.threatPos=()=>({x:1e7,z:1e7,loud:0});
